/* Hidden safeguard rule */
[hidden] {
  display: none !important;
}

:root {
  --color-bg: #1a1a2e;
  --color-card: #16213e;
  --color-accent: #0f3460;
  --color-gold: #f5a623;
  --color-gold-hover: #e09415;
  --color-cyan: #4ecca3;
  --color-cyan-hover: #3db890;
  --color-text: #e94560;
  --color-light: #f1f1f1;
  --color-subtle: #a0a5b5;
  --color-danger: #ff4757;
  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  background-color: var(--color-bg);
  color: var(--color-light);
  font-family: var(--font-family);
  font-size: 16px;
  padding: 1rem;
}

.auction-card {
  background-color: var(--color-card);
  width: 100%;
  max-width: 440px;
  border-radius: 12px;
  border: 3px solid var(--color-accent);
  padding: 1.75rem;
  box-shadow: 0 16px 32px rgba(0, 0, 0, 0.45);
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.auction-header {
  text-align: center;
}

.badge {
  display: inline-block;
  background-color: var(--color-danger);
  color: #fff;
  font-size: 0.75rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  padding: 0.25rem 0.6rem;
  border-radius: 4px;
  margin-bottom: 0.5rem;
}

.item-title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--color-light);
  margin-bottom: 0.25rem;
}

.item-subtitle {
  font-size: 0.875rem;
  color: var(--color-subtle);
}

.preview-container {
  background-color: var(--color-bg);
  border: 2px dashed var(--color-accent);
  border-radius: 8px;
  padding: 1.25rem;
  display: flex;
  justify-content: center;
  align-items: center;
}

#pixelCanvas {
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  width: 128px;
  height: 128px;
}

.stats-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.stat-box {
  background-color: var(--color-accent);
  border-radius: 8px;
  padding: 0.9rem;
  text-align: center;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.stat-label {
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: var(--color-subtle);
}

.stat-value {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--color-light);
}

.stat-box.urgent #timerDisplay {
  color: var(--color-danger);
  animation: pulse 1s infinite alternate;
}

@keyframes pulse {
  from { transform: scale(1); }
  to { transform: scale(1.08); }
}

.action-section {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.bid-buttons-group {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.85rem;
}

.btn {
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: 700;
  padding: 0.85rem 1rem;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  transition: background-color 0.15s ease, transform 0.08s ease;
  outline-offset: 3px;
}

.btn:focus-visible {
  outline: 3px solid #ffffff;
}

.btn-primary {
  background-color: var(--color-gold);
  color: #1a1a2e;
}

.btn-primary:hover:not(:disabled) {
  background-color: var(--color-gold-hover);
}

.btn-secondary {
  background-color: var(--color-cyan);
  color: #1a1a2e;
}

.btn-secondary:hover:not(:disabled) {
  background-color: var(--color-cyan-hover);
}

.btn:active:not(:disabled) {
  transform: translateY(2px);
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
}

.status-banner {
  background-color: var(--color-text);
  color: #ffffff;
  text-align: center;
  padding: 1rem;
  border-radius: 8px;
  font-size: 1.25rem;
  font-weight: 800;
  box-shadow: 0 4px 12px rgba(233, 69, 96, 0.4);
}

.auction-footer {
  text-align: center;
  border-top: 1px solid var(--color-accent);
  padding-top: 0.85rem;
}

.rule-note {
  font-size: 0.8rem;
  color: var(--color-subtle);
}

@media (max-width: 360px) {
  .auction-card {
    padding: 1.25rem;
    gap: 1.1rem;
  }

  .stat-value {
    font-size: 1.25rem;
  }

  .btn {
    font-size: 1rem;
    padding: 0.75rem 0.5rem;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  // State
  let currentPrice = 10;
  let timeLeft = 45;
  let timerId = null;
  let isAuctionEnded = false;

  // DOM Elements
  const bidAmountSpan = document.getElementById('currentBidAmount');
  const timerDisplay = document.getElementById('timerDisplay');
  const timerBox = document.getElementById('timerBox');
  const bid1Btn = document.getElementById('bid1Btn');
  const bid5Btn = document.getElementById('bid5Btn');
  const statusMessage = document.getElementById('statusMessage');
  const canvas = document.getElementById('pixelCanvas');

  // Draw a 16x16 pixel sword
  function drawPixelItem() {
    if (!canvas || !canvas.getContext) return;
    const ctx = canvas.getContext('2d');
    const pixelSize = 8; // 16 * 8 = 128 canvas width/height

    const swordPixels = [
      // [x, y, color]
      // Blade tip & edge
      [11, 2, '#ffffff'], [12, 3, '#ffffff'], [13, 4, '#ffffff'],
      [10, 3, '#4ecca3'], [11, 3, '#e0fcf4'], [12, 4, '#e0fcf4'], [11, 4, '#4ecca3'],
      [9, 4, '#4ecca3'], [10, 4, '#e0fcf4'], [10, 5, '#4ecca3'],
      [8, 5, '#4ecca3'], [9, 5, '#e0fcf4'], [9, 6, '#4ecca3'],
      [7, 6, '#4ecca3'], [8, 6, '#e0fcf4'], [8, 7, '#4ecca3'],
      [6, 7, '#4ecca3'], [7, 7, '#e0fcf4'], [7, 8, '#4ecca3'],
      [5, 8, '#4ecca3'], [6, 8, '#e0fcf4'], [6, 9, '#4ecca3'],
      // Guard
      [7, 9, '#f5a623'], [4, 9, '#f5a623'], [5, 10, '#f5a623'], [6, 10, '#d48810'],
      [3, 10, '#f5a623'], [7, 10, '#f5a623'], [2, 11, '#d48810'],
      // Handle
      [4, 11, '#8b4513'], [3, 12, '#5c2c09'],
      // Pommel
      [2, 13, '#f5a623'], [1, 13, '#d48810'], [2, 14, '#d48810']
    ];

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (const [x, y, color] of swordPixels) {
      ctx.fillStyle = color;
      ctx.fillRect(x * pixelSize, y * pixelSize, pixelSize, pixelSize);
    }
  }

  function updateTimerUI() {
    timerDisplay.textContent = `${timeLeft}s`;
    if (timeLeft <= 10) {
      timerBox.classList.add('urgent');
    } else {
      timerBox.classList.remove('urgent');
    }
  }

  function handleBid(increment) {
    if (isAuctionEnded) return;

    currentPrice += increment;
    bidAmountSpan.textContent = currentPrice.toString();

    // Anti-sniping rule: if bid in last 10 seconds, reset timer to 10s
    if (timeLeft <= 10) {
      timeLeft = 10;
      updateTimerUI();
    }
  }

  function finishAuction() {
    isAuctionEnded = true;
    clearInterval(timerId);
    timeLeft = 0;
    updateTimerUI();

    bid1Btn.disabled = true;
    bid5Btn.disabled = true;

    // Display required 'Sold for N'
    statusMessage.textContent = `Sold for ${currentPrice}`;
    statusMessage.removeAttribute('hidden');
  }

  function tick() {
    if (timeLeft > 0) {
      timeLeft -= 1;
      updateTimerUI();
      if (timeLeft <= 0) {
        finishAuction();
      }
    }
  }

  // Attach Event Listeners
  bid1Btn.addEventListener('click', () => handleBid(1));
  bid5Btn.addEventListener('click', () => handleBid(5));

  // Initialize
  drawPixelItem();
  updateTimerUI();
  timerId = setInterval(tick, 1000);
});
